// auth-security · кейсы auth-03, auth-08, auth-09, auth-10 (.qa/tests/auth-security/)
import { test, expect } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

// Заказ другого клиента («פיצוציה בע'ם», #367) — виден מפיץ, не принадлежит buyer («test»).
// Если тестовые данные пересоздадут — взять любой id заказа чужого клиента у админа.
const FOREIGN_ORDER_ID = 'a898c48d-5c5a-43a6-8590-22138a608459';
const MISSING_ORDER_ID = '00000000-0000-0000-0000-000000000000';

test.describe('auth-security — בידוד נתוני לקוח', () => {
  test.use({ storageState: auth('buyer') });

  test('לקוח לא נכנס למסכי הניהול — מופנה ל-/shop #6a38cf59 #6a749714 @desktop @prod-safe', async ({ page }) => {
    for (const route of ['/catalog', '/team', '/customers', '/orders', `/orders/${FOREIGN_ORDER_ID}`]) {
      await page.goto(route);
      await expect(page, `маршрут ${route}`).toHaveURL(/\/shop/);
      await expect(page.getByText('צוות והרשאות')).toHaveCount(0);
      await expect(page.getByText('כניסה כעובד')).toHaveCount(0);
    }
  });

  test('לקוח פותח הזמנה של לקוח אחר — «אין הרשאה»; הזמנה לא קיימת — «לא נמצאה» #6a38cf5a @prod-safe', async ({ page }) => {
    await page.goto(`/shop/order/${FOREIGN_ORDER_ID}`);
    await expect(page.getByText('אין הרשאה לצפות בהזמנה זו — היא שייכת ללקוח אחר.')).toBeVisible();
    await expect(page.getByText('חזרה להזמנות')).toBeVisible();
    await expect(page.getByText(/הזמנה #367/)).toHaveCount(0);

    await page.goto(`/shop/order/${MISSING_ORDER_ID}`);
    await expect(page.getByText('ההזמנה לא נמצאה.')).toBeVisible();
  });

  test('RLS: ה-API מחזיר ללקוח רק את ההזמנות והלקוח שלו #6a38cf5a @desktop @prod-safe', async ({ page }) => {
    await page.goto('/shop');
    await expect(page.getByText('שלום,').first()).toBeVisible();
    const res = await page.evaluate(async (foreignId) => {
      let key: string | null = null;
      for (const src of [...document.scripts].map((s) => s.src).filter(Boolean)) {
        const t = await (await fetch(src)).text();
        const m = t.match(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/);
        if (m) { key = m[0]; break; }
      }
      const tokenKey = Object.keys(localStorage).find((k) => k.includes('auth-token'))!;
      const token = JSON.parse(localStorage.getItem(tokenKey)!).access_token;
      const base = (JSON.parse(atob(key!.split('.')[1])).ref as string);
      const url = `https://${base}.supabase.co/rest/v1`;
      const h = { apikey: key!, Authorization: `Bearer ${token}` };
      const own = await (await fetch(`${url}/orders?select=id,customer_id&limit=1000`, { headers: h })).json();
      const foreign = await fetch(`${url}/orders?select=id&id=eq.${foreignId}`, { headers: h });
      const customers = await (await fetch(`${url}/customers?select=id`, { headers: h })).json();
      return {
        ownCustomerIds: [...new Set((own as { customer_id: string }[]).map((o) => o.customer_id))],
        foreignStatus: foreign.status,
        foreignRows: (await foreign.json()).length,
        customers: (customers as unknown[]).length,
      };
    }, FOREIGN_ORDER_ID);
    expect(res.ownCustomerIds.length).toBeLessThanOrEqual(1);
    expect(res.foreignRows).toBe(0);
    expect(res.customers).toBe(1);
  });

  test('שני לקוחות — מחירים והיסטוריה מבודדים, לקוח חדש — רשימה ריקה #6a38cf5a', async () => {
    test.skip(true, 'нужен аккаунт buyer2 (второй לקוח)');
  });
});
